// Service configuration, loaded from an env-file style string.

export interface Config {
  port: number;
  host: string;
  appName: string;
  debug: boolean;
  motd: string;
}

const LINE = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/;

// Parses an env-file style string: KEY=value per line, `#` comments, and
// single- or double-quoted values (quotes protect `#` and surrounding spaces).
export function parseEnvFile(text: string): Record<string, string> {
  const env: Record<string, string> = {};

  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) continue;

    const match = LINE.exec(line);
    if (!match) throw new Error(`invalid env line: ${raw}`);
    const [, key, rest] = match;

    env[key] = rest.startsWith('"') || rest.startsWith("'")
      ? readQuoted(rest, raw)
      : rest.replace(/(?:^|\s)#.*$/, "").trim();
  }

  return env;
}

// Reads a quoted value and verifies nothing but a comment follows the closing
// quote. Double quotes honour backslash escapes; single quotes stay literal.
function readQuoted(rest: string, raw: string): string {
  const quote = rest[0];
  let value = "";

  for (let i = 1; i < rest.length; i++) {
    const char = rest[i];
    if (char === "\\" && quote === '"' && i + 1 < rest.length) {
      value += unescape(rest[++i]);
      continue;
    }
    if (char === quote) {
      const trailing = rest.slice(i + 1).trim();
      if (trailing !== "" && !trailing.startsWith("#")) {
        throw new Error(`unexpected text after quoted value: ${raw}`);
      }
      return value;
    }
    value += char;
  }

  throw new Error(`unterminated quote: ${raw}`);
}

function unescape(char: string): string {
  switch (char) {
    case "n": return "\n";
    case "r": return "\r";
    case "t": return "\t";
    default: return char;
  }
}

export function loadConfig(text: string): Config {
  const env = parseEnvFile(text);
  const port = Number(env.PORT ?? "8080");
  if (!Number.isInteger(port) || port <= 0) throw new Error(`invalid PORT: ${env.PORT}`);
  return {
    port,
    host: env.HOST ?? "127.0.0.1",
    appName: env.APP_NAME ?? "order-service",
    debug: (env.DEBUG ?? "false").toLowerCase() === "true",
    motd: env.MOTD ?? "",
  };
}

